#include <stack>
#include <iostream>

int main() {
    std::stack<int> s;

    // Recommended check for emptiness
    if (s.empty()) {
        std::cout << "Stack is empty (Preferred method).\n";
    }

    // Logically equivalent, but discouraged for checking emptiness alone
    if (s.size() == 0) {
        std::cout << "Stack size is zero (Discouraged style).\n";
    }

    s.push(1);
    // Check after insertion
    if (!s.empty()) {
        std::cout << "Stack is not empty.\n";
    }
}
